'use strict';
const questions = [
 {topic:'01 · Arbeit zu Hause',emoji:'🧵',q:'Noch keine Fabrik in Sicht: Wie funktionierte das Verlagssystem?',quip:'Homeoffice gab es schon – nur ohne Videokonferenz.',answers:['Familien produzierten zu Hause; Händler lieferten Rohstoffe und verkauften die Waren.','Alle Familien verkauften ausschliesslich ihre eigenen Ernten.','Der Staat stellte alle Menschen in grossen Fabriken an.','Verlage druckten Anleitungen für die ersten Computer.'],correct:0,explain:'Im Verlagssystem erledigten Familien etwa Spinn- und Webarbeiten zu Hause. Händler lieferten die Rohstoffe und übernahmen den Verkauf. Viele Familien kombinierten Heimarbeit und Landwirtschaft.',source:'Text, S. 1'},
 {topic:'02 · Die Maschinen kommen',emoji:'⚙️',q:'Was veränderte sich mit der Industrialisierung grundlegend?',quip:'Der Webstuhl bekommt technische Verstärkung.',answers:['Maschinen wurden durch reine Handarbeit ersetzt.','Die gesamte Bevölkerung wechselte sofort in Fabriken.','Mehr Arbeitsschritte wurden mechanisiert; ein Teil der Produktion wanderte in Fabriken.','Handel und Lohnarbeit verschwanden.'],correct:2,explain:'Maschinen übernahmen zunehmend Arbeitsschritte. Die Produktion verlagerte sich teilweise von Haushalten in Fabriken. Dieser Wandel geschah nach und nach.',source:'Text, S. 3'},
 {topic:'03 · Schweizer Frühstarter',emoji:'⌚',q:'Welche Branchen waren am Anfang besonders wichtig?',quip:'Was lief schon, bevor jemand «Hightech» sagte?',answers:['Automobilbau und Flugzeugbau.','Baumwoll- und Seidenindustrie sowie Uhrmacherei.','Erdölförderung und Stahlindustrie.','App-Entwicklung und Streaming.'],correct:1,explain:'Die Baumwoll- und Seidenindustrie sowie die Uhrmacherei waren wichtige frühe Branchen. Heimarbeit, handwerkliches Wissen und Handelskontakte bildeten dafür eine Grundlage.',source:'Text, S. 1 und 3'},
 {topic:'04 · Nächster Halt: Wachstum',emoji:'🚂',q:'Warum war der Ausbau der Eisenbahn so wichtig?',quip:'Die Wirtschaft bekam Anschluss. Ganz ohne WLAN.',answers:['Er machte den Handel mit dem Ausland unnötig.','Er sorgte dafür, dass Rohstoffe nicht mehr gebraucht wurden.','Er diente nur dem Sonntagsausflug.','Er erleichterte Transporte und verband Unternehmen mit neuen Märkten.'],correct:3,explain:'Die Bahn transportierte Menschen, Rohstoffe und Waren und verbesserte den Zugang zu Märkten. Die Karten um 1860 und vor 1914 veranschaulichen den Ausbau des Netzes.',source:'Text, S. 3 und 5; Notizseiten, S. 1–2'},
 {topic:'05 · Weniger Schranken',emoji:'🇨🇭',q:'Was erleichterte der Bundesstaat von 1848 für die Wirtschaft?',quip:'Weniger Hindernisse zwischen den Kantonen – mehr Austausch.',answers:['Er beseitigte Binnenzölle und vereinheitlichte den Binnenmarkt.','Er führte an jeder Kantonsgrenze neue Zölle ein.','Er verbot den Bau von Eisenbahnen.','Er schaffte das Geld ab: Bezahlt wurde nur noch mit Käse.'],correct:0,explain:'Mit dem Bundesstaat wurden wirtschaftliche Hindernisse abgebaut. Binnenzölle entfielen; Geldwesen, Post und Telegrafie wurden besser organisiert.',source:'Text, S. 5'},
 {topic:'06 · Klein, aber international',emoji:'🌍',q:'Warum setzten Schweizer Firmen auf Export, Qualität und Spezialprodukte?',quip:'Der heimische Markt war eben kein XXL-Warenkorb.',answers:['Weil die Schweiz der grösste Binnenmarkt Europas war.','Weil ausländische Konkurrenz gesetzlich ausgeschlossen war.','Weil der Binnenmarkt klein und die internationale Konkurrenz stark war.','Weil im Inland überhaupt niemand Waren kaufte.'],correct:2,explain:'Der kleine Binnenmarkt machte Exporte wichtig. Im internationalen Wettbewerb halfen Spezialisierung, Qualität und Innovation.',source:'Text, S. 3'},
 {topic:'07 · Energie mit Gefälle',emoji:'💧',q:'Was bezeichnete man als «weisse Kohle»?',quip:'Tipp: Sie kommt nicht aus einer frisch gewaschenen Mine.',answers:['Besonders helles Gestein für Dampfmaschinen.','Wasserkraft zur Erzeugung von Elektrizität.','Importierte Kohle aus schneereichen Ländern.','Baumwolle als Brennstoff für Lokomotiven.'],correct:1,explain:'«Weisse Kohle» meint Wasserkraft. Da die Schweiz wenig Kohle hatte, wurde die Stromerzeugung aus Wasser zu einem grossen Vorteil für ihre Industrie.',source:'Text, S. 5'},
 {topic:'08 · Die Schweiz wandelt sich weiter',emoji:'💻',q:'Welcher Sektor wurde seit den 1970er-Jahren immer wichtiger?',quip:'Letzte Frage: Die Wirtschaft hat mehr als einen Gang.',answers:['Die Landwirtschaft löste alle anderen Bereiche ab.','Die Textilindustrie wurde wieder der einzige Wirtschaftszweig.','Heimarbeit im Verlagssystem verdrängte die Fabriken.','Der Dienstleistungssektor, etwa Handel, Banken und Tourismus.'],correct:3,explain:'In den 1970er-Jahren endete die Vorherrschaft der Industrie. Dienstleistungen wurden wichtiger. Informatik und Mikroelektronik veränderten gleichzeitig auch die Industrie weiter.',source:'Text, S. 5'}
];
const $=id=>document.getElementById(id);let index=0;let responses=[];
function points(){return responses.filter((a,i)=>a===questions[i].correct).length}
function render(focus=false){const item=questions[index];$('play').hidden=false;$('result').hidden=true;$('counter').textContent=`FRAGE ${String(index+1).padStart(2,'0')} / 08`;$('score').textContent=`${points()} ${points()===1?'Punkt':'Punkte'}`;$('progress').value=responses.length;$('topic').textContent=item.topic;$('emoji').textContent=item.emoji;$('question').textContent=item.q;$('quip').textContent=item.quip;$('answers').replaceChildren();$('feedback').hidden=true;$('next').hidden=true;item.answers.forEach((answer,i)=>{const button=document.createElement('button');button.className='answer';button.innerHTML=`<span class="letter" aria-hidden="true">${'ABCD'[i]}</span><span></span>`;button.lastChild.textContent=answer;button.addEventListener('click',()=>answerQuestion(i));$('answers').append(button)});if(focus)$('question').focus()}
function answerQuestion(choice){if(!Number.isInteger(choice)||choice<0||choice>3||responses.length!==index)throw new Error('Diese Antwort ist gerade nicht möglich.');const item=questions[index];responses.push(choice);[...$('answers').children].forEach((b,i)=>{b.disabled=true;if(i===item.correct){b.classList.add('correct');b.lastChild.textContent+=' ✓ Richtig'}else if(i===choice){b.classList.add('wrong');b.lastChild.textContent+=' ✕ Deine Antwort'}});const correct=choice===item.correct;const feedback=$('feedback');feedback.className='feedback'+(correct?'':' missed');feedback.replaceChildren();const title=document.createElement('strong');title.textContent=correct?'Richtig! Das läuft wie geschmiert.':'Noch nicht ganz – hier kommt der Aha-Moment.';const explanation=document.createElement('span');explanation.textContent=item.explain;const reference=document.createElement('small');reference.className='reference';reference.textContent=`Grundlage: ${item.source}`;feedback.append(title,explanation,reference);feedback.hidden=false;$('score').textContent=`${points()} ${points()===1?'Punkt':'Punkte'}`;$('progress').value=responses.length;$('next').textContent=index===7?'Zur Auswertung →':'Weiter →';$('next').hidden=false;return state()}
function nextQuestion(){if(responses.length!==index+1)throw new Error('Bitte zuerst antworten.');index++;if(index===questions.length)finish();else render(true);return state()}
function finish(){$('play').hidden=true;$('result').hidden=false;$('counter').textContent='SCHICHT GESCHAFFT';const p=points();const title=p>=7?'Volldampf-Profi!':p>=4?'Die Maschine läuft!':'Der Motor wird warm!';const message=p>=7?'Du hast die Grundlagen im Griff. Die nächste Zeitreise kann kommen.':p>=4?'Eine gute Basis! Schau dir die offenen Punkte an, dann läuft es noch runder.':'Der Anfang ist gemacht. Lies die Erklärungen unten und probiere es nochmals – ohne Schichtstress.';$('result').innerHTML=`<p class="eyebrow">DEINE WISSENSBILANZ</p><p class="result-number">${p}<span> / 8 Punkte</span></p><h2 id="result-title" tabindex="-1">${title}</h2><p class="quip">${message}</p><button class="primary" id="restart">Noch eine Runde ↻</button><details class="review"><summary>Alle Antworten &amp; Erklärungen</summary><div id="review-items"></div></details>`;questions.forEach((q,i)=>{const article=document.createElement('article');const h=document.createElement('h3');h.textContent=`${responses[i]===q.correct?'✓':'✕'} ${i+1}. ${q.q}`;const own=document.createElement('p');own.textContent=`Deine Antwort: ${q.answers[responses[i]]}`;const correct=document.createElement('p');correct.textContent=`Richtig: ${q.answers[q.correct]}`;const explanation=document.createElement('p');explanation.textContent=q.explain;article.append(h,own,correct,explanation);$('review-items').append(article)});$('restart').onclick=restart;$('result-title').focus()}
function restart(){index=0;responses=[];render(true);return state()}
function state(){return {screen:index===8?'result':'question',question:index<8?questions[index].q:null,choices:index<8?questions[index].answers:[],questionNumber:Math.min(index+1,8),answered:responses.length,points:points()}}
$('next').onclick=nextQuestion;render();
if(document.modelContext?.registerTool){const abort=new AbortController();for(const tool of [{name:'quiz_state',description:'Liest die aktuelle Quizfrage und den Punktestand.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:state},{name:'answer_quiz_question',description:'Beantwortet die aktuelle Frage verbindlich. choice ist 0, 1, 2 oder 3.',inputSchema:{type:'object',properties:{choice:{type:'integer',minimum:0,maximum:3}},required:['choice'],additionalProperties:false},execute:input=>answerQuestion(input.choice)},{name:'next_quiz_question',description:'Öffnet nach einer Antwort die nächste Frage oder die Auswertung.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:nextQuestion},{name:'restart_quiz',description:'Setzt alle Antworten und Punkte zurück und startet eine neue Runde.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:restart}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:abort.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>abort.abort(),{once:true})}
